import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_kernel_code = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_sigmoid_scale_add_kernel(
    const float* input,
    const float* original,
    float* output,
    float scaling_factor,
    int num_elements
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        float val = input[idx];
        float sigmoid_val = 1.0f / (1.0f + expf(-val));
        output[idx] = sigmoid_val * scaling_factor + original[idx];
    }
}

torch::Tensor fused_op_cuda(torch::Tensor input, torch::Tensor original, float scaling_factor) {
    auto output = torch::empty_like(input);
    int num_elements = input.numel();

    const int block_size = 256;
    int grid_size = (num_elements + block_size - 1) / block_size;

    fused_sigmoid_scale_add_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        original.data_ptr<float>(),
        output.data_ptr<float>(),
        scaling_factor,
        num_elements
    );

    return output;
}
"""

fused_kernel_cpp = "torch::Tensor fused_op_cuda(torch::Tensor input, torch::Tensor original, float scaling_factor);"

fused_op = load_inline(
    name='fused_op',
    cpp_sources=fused_kernel_cpp,
    cuda_sources=fused_kernel_code,
    functions=['fused_op_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, input_size, hidden_size, scaling_factor):
        super(ModelNew, self).__init__()
        self.gemm = nn.Linear(input_size, hidden_size)
        self.scaling_factor = scaling_factor
        self.fused_op = fused_op

    def forward(self, x):
        original = self.gemm(x)
        return self.fused_op.fused_op_cuda(torch.sigmoid(original), original, self.scaling_factor)
